/****************************************************************************
 * LCKFB Huangshan Pi (黄山派) Board Initialization
 *
 * VelaWear - 基于 OpenVela 的低功耗多模态 AI 智能穿戴 Agent
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/board.h>
#include <nuttx/serial/serial.h>
#include <syslog.h>

#include "chip.h"
#include "board.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: board_uart_initialize
 *
 * Description:
 *   Initialize UART for console.
 *
 ****************************************************************************/

static void board_uart_initialize(void)
{
  /* UART0 is configured as console in defconfig */
  syslog(LOG_INFO, "UART0 initialized as console\n");
}

/****************************************************************************
 * Name: board_i2c_initialize
 *
 * Description:
 *   Initialize I2C bus for IMU sensor.
 *
 ****************************************************************************/

static void board_i2c_initialize(void)
{
#ifdef CONFIG_SF32LB52_I2C0
  /* I2C0 initialization for IMU (LSM6DSO) */
  syslog(LOG_INFO, "I2C0 initialized for IMU sensor\n");
#endif
}

/****************************************************************************
 * Name: board_spi_initialize
 *
 * Description:
 *   Initialize SPI bus for LCD display.
 *
 ****************************************************************************/

static void board_spi_initialize(void)
{
#ifdef CONFIG_SF32LB52_SPI0
  /* SPI0 initialization for LCD */
  syslog(LOG_INFO, "SPI0 initialized for LCD display\n");
#endif
}

/****************************************************************************
 * Name: board_ble_initialize
 *
 * Description:
 *   Initialize BLE controller.
 *
 ****************************************************************************/

static void board_ble_initialize(void)
{
#ifdef CONFIG_SF32LB52_BLE
  /* BLE initialization */
  syslog(LOG_INFO, "BLE 5.3 controller initialized\n");
#endif
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: board_late_initialize
 *
 * Description:
 *   Board late initialization.
 *
 ****************************************************************************/

int board_late_initialize(void)
{
  syslog(LOG_INFO, "LCKFB Huangshan Pi board initialization\n");

  /* Initialize peripherals */
  board_uart_initialize();
  board_i2c_initialize();
  board_spi_initialize();
  board_ble_initialize();

  syslog(LOG_INFO, "Board initialization complete\n");

  return OK;
}

